command:
set -euo pipefail
export PATH=/opt/conda/bin:$PATH
export TMPDIR=/tmp HOME=/tmp
cd /tmp

echo "== 20 kb reference; the SAMPLE carries a 1000 bp deletion of ref[8001..9000] =="
awk 'BEGIN{srand(13); b="ACGT"; s=""
  for(i=0;i<20000;i++) s=s substr(b,int(rand()*4)+1,1)
  print ">chrS"; for(i=1;i<=length(s);i+=60) print substr(s,i,60) }' > ref.fa
REF=$(awk '!/^>/{printf "%s",$0}' ref.fa)
SAMPLE="${REF:0:8000}${REF:9000}"
printf 'del_start\t8001\ndel_end\t9000\ndel_len\t1000\nref_len\t%s\nsample_len\t%s\n' "${#REF}" "${#SAMPLE}" > truth.tsv
cat truth.tsv

echo "== fixture identity: the sample must be shorter by exactly the deleted length =="
test "${#REF}"    = 20000 || { echo "FIXTURE: reference is not 20000 bp"; exit 1; }
test "${#SAMPLE}" = 19000 || { echo "FIXTURE: sample is not 19000 bp"; exit 1; }
test $(( ${#REF} - ${#SAMPLE} )) = 1000 || { echo "FIXTURE: length difference is not the deletion"; exit 1; }
echo "fixture_lengths	ref 20000 - sample 19000 = 1000 = the planted deletion"

echo "== paired reads FROM THE SAMPLE: 100 bp, fragments 360-440 (median 400, nonzero MAD) =="
awk -v s="$SAMPLE" 'BEGIN{
  RL=100; STRIDE=6; n=0
  nf = split("360 380 400 420 440", FL, " ")
  q=""; for(i=0;i<RL;i++) q=q "I"
  for(p=1; p+440-1<=length(s); p+=STRIDE){
    n++; FR=FL[(n%nf)+1]
    r1=substr(s,p,RL); r2=substr(s,p+FR-RL,RL); rc=""
    for(j=length(r2);j>=1;j--){ c=substr(r2,j,1)
      rc = rc (c=="A"?"T":(c=="T"?"A":(c=="C"?"G":(c=="G"?"C":"N")))) }
    printf "@f%d/1\n%s\n+\n%s\n", n, r1, q > "R1.fq"
    printf "@f%d/2\n%s\n+\n%s\n", n, rc, q > "R2.fq"
  }
  # one last fragment anchored at the end, so the ONLY coverage gap is the deletion
  p=length(s)-440+1; n++; FR=440
  r1=substr(s,p,RL); r2=substr(s,p+FR-RL,RL); rc=""
  for(j=length(r2);j>=1;j--){ c=substr(r2,j,1)
    rc = rc (c=="A"?"T":(c=="T"?"A":(c=="C"?"G":(c=="G"?"C":"N")))) }
  printf "@f%d/1\n%s\n+\n%s\n", n, r1, q > "R1.fq"
  printf "@f%d/2\n%s\n+\n%s\n", n, rc, q > "R2.fq"
  printf "fixture_reads\t%d fragments / %.1fx / fragment lengths 360-440\n", n, n*2*RL/19000
}' | tee fixture.txt

echo "== align the sample's reads back to the REFERENCE, so the deletion must be inferred =="
bwa index ref.fa 2> bwaindex.log
bwa mem -t 1 -R '@RG\tID:s1\tSM:sample1\tPL:ILLUMINA' ref.fa R1.fq R2.fq > aln.sam 2> bwamem.log
NREC=$(awk '!/^@/{n++} END{print n+0}' aln.sam)
NSA=$(awk '/SA:Z:/{n++} END{print n+0}' aln.sam)
NRG=$(awk '/^@RG/{n++} END{print n+0}' aln.sam)
test "$NRG" -ge 1  || { echo "no @RG in the BAM header -- delly requires a read group with SM"; exit 1; }
test "$NSA" -gt 0  || { echo "no SA:Z split alignments -- delly could only call an IMPRECISE breakpoint"; exit 1; }
{
printf 'sam_records\t%s\n' "$NREC"
printf 'split_alignments\t%s   (assert >0 -- split reads are what make an EXACT breakpoint possible)\n' "$NSA"
printf 'read_groups\t%s   (assert >=1 -- delly refuses a BAM with no @RG SM)\n' "$NRG"
} | tee -a fixture.txt
echo "ALIGN OK"
